import React, { useState } from 'react';
import { GoogleAuthProvider, FacebookAuthProvider, signInWithPopup } from "firebase/auth";
import { auth } from '../firebaseConfig';

export default function ClientLoginModal({ show, onClose, onLogin }) {
  const [isRegistering, setIsRegistering] = useState(false);
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: '',
    phone: ''
  });
  const [error, setError] = useState('');

  if (!show) return null;

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setError('');
    
    // محاكاة قاعدة بيانات المستخدمين في LocalStorage
    const users = JSON.parse(localStorage.getItem('site_users') || '[]');

    if (isRegistering) {
      // تسجيل حساب جديد
      if (!formData.name || !formData.email || !formData.password) {
        return setError('يرجى ملء كافة الحقول المطلوبة (*)');
      }
      
      if (users.find(u => u.email === formData.email)) {
        return setError('هذا البريد الإلكتروني مسجل مسبقاً');
      }

      const newUser = {
        id: 'user-' + Date.now(),
        name: formData.name,
        email: formData.email,
        password: formData.password, // تنبيه: في التطبيق الحقيقي يجب تشفير كلمة المرور
        phone: formData.phone,
        provider: 'local',
        joinedAt: new Date().toISOString()
      };

      localStorage.setItem('site_users', JSON.stringify([...users, newUser]));
      onLogin(newUser);
    } else {
      // تسجيل الدخول
      if (!formData.email || !formData.password) {
        return setError('يرجى إدخال البريد الإلكتروني وكلمة المرور');
      }

      const user = users.find(u => u.email === formData.email && u.password === formData.password);
      if (user) {
        onLogin(user);
      } else {
        setError('البريد الإلكتروني أو كلمة المرور غير صحيحة');
      }
    }
  };

  const handleGoogleLogin = async () => {
    try {
      const provider = new GoogleAuthProvider();
      const result = await signInWithPopup(auth, provider);
      const user = result.user;
      
      const appUser = {
        id: user.uid,
        name: user.displayName || 'مستخدم جوجل',
        email: user.email,
        photo: user.photoURL,
        provider: 'google'
      };
      onLogin(appUser);
    } catch (error) {
      console.error("Google Login Error:", error);
      setError("فشل تسجيل الدخول عبر جوجل. تأكد من إعدادات Firebase.");
    }
  };

  const handleFacebookLogin = async () => {
    try {
      const provider = new FacebookAuthProvider();
      const result = await signInWithPopup(auth, provider);
      const user = result.user;

      const appUser = {
        id: user.uid,
        name: user.displayName || 'مستخدم فيسبوك',
        email: user.email,
        photo: user.photoURL,
        provider: 'facebook'
      };
      onLogin(appUser);
    } catch (error) {
      console.error("Facebook Login Error:", error);
      if (error.code === 'auth/account-exists-with-different-credential') {
        setError("يوجد حساب بنفس البريد الإلكتروني مسجل بطريقة أخرى (مثل جوجل).");
      } else {
        setError("فشل تسجيل الدخول عبر فيسبوك. تأكد من إعدادات التطبيق في لوحة تحكم فيسبوك و Firebase.");
      }
    }
  };

  return (
    <div className="modal fade show d-block" tabIndex="-1" style={{ background: 'rgba(0,0,0,0.6)', zIndex: 1080 }}>
      <div className="modal-dialog modal-dialog-centered">
        <div className="modal-content shadow-lg border-0 overflow-hidden">
          <div className="modal-header border-0 bg-light">
            <h5 className="modal-title fw-bold">{isRegistering ? '📝 إنشاء حساب جديد' : '👋 تسجيل الدخول'}</h5>
            <button type="button" className="btn-close" onClick={onClose}></button>
          </div>
          <div className="modal-body p-4">
            
            {error && <div className="alert alert-danger py-2 small">{error}</div>}

            <form onSubmit={handleSubmit}>
              {isRegistering && (
                <div className="mb-3">
                  <label className="form-label small fw-bold">الاسم بالكامل *</label>
                  <input 
                    type="text" 
                    className="form-control" 
                    name="name" 
                    value={formData.name} 
                    onChange={handleChange} 
                    placeholder="الاسم" 
                  />
                </div>
              )}

              <div className="mb-3">
                <label className="form-label small fw-bold">البريد الإلكتروني *</label>
                <input 
                  type="email" 
                  className="form-control" 
                  name="email" 
                  value={formData.email} 
                  onChange={handleChange} 
                  placeholder="name@example.com" 
                />
              </div>

              <div className="mb-3">
                <label className="form-label small fw-bold">كلمة المرور *</label>
                <input 
                  type="password" 
                  className="form-control" 
                  name="password" 
                  value={formData.password} 
                  onChange={handleChange} 
                  placeholder="********" 
                />
              </div>

              {isRegistering && (
                <div className="mb-3">
                  <label className="form-label small fw-bold">رقم الهاتف (اختياري)</label>
                  <input 
                    type="tel" 
                    className="form-control" 
                    name="phone" 
                    value={formData.phone} 
                    onChange={handleChange} 
                    placeholder="01xxxxxxxxx" 
                  />
                </div>
              )}

              <div className="d-grid mb-3">
                <button type="submit" className="btn btn-primary fw-bold">
                  {isRegistering ? 'إنشاء الحساب' : 'دخول'}
                </button>
              </div>
            </form>

            <div className="text-center mb-3">
              <span className="text-muted small">أو الاستمرار باستخدام</span>
            </div>

            <div className="d-flex gap-2 justify-content-center mb-4">
              <button className="btn btn-outline-danger btn-sm flex-grow-1" onClick={handleGoogleLogin}>
                <span className="me-1">🔴</span> Google
              </button>
              <button className="btn btn-outline-primary btn-sm flex-grow-1" onClick={handleFacebookLogin}>
                <span className="me-1">🔵</span> Facebook
              </button>
            </div>
            
            <div className="text-center border-top pt-3">
              <small className="text-muted">
                {isRegistering ? 'لديك حساب بالفعل؟' : 'ليس لديك حساب؟'}
                <button 
                  className="btn btn-link btn-sm text-decoration-none fw-bold" 
                  onClick={() => { setIsRegistering(!isRegistering); setError(''); }}
                >
                  {isRegistering ? 'تسجيل الدخول' : 'إنشاء حساب جديد'}
                </button>
              </small>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
